    def edge_tracking(self):
        try:
            color_channel = [0 if self.edge_track_color_box.currentText() == 'R'
                            else 1 if self.edge_track_color_box.currentText() == 'B' else 2][0]
            w = self.edge_track_width_box.value()
            mu = self.mu_box.value()
            l = self.l_box.value()
            p = self.p_box.value()

            res = ct.segmentation.edges_tracking(
                self.image_crop[:, :, color_channel],
                self.pts_crop,
                self.edge_mask1_crop, self.edge_mask2_crop, self.adjusted_track, mu=mu, l=l, p=p,
                return_normal_edges=True
            )

            track_e1, track_e2 = res["geodesic_edges"]
            normal_edges = res["normal_edge_points"]
            normal_edges_clipped = res["normal_edge_points_clipped"]

            # ---- Respect pre-assigned crack ID (set in run_pipeline) ----
            if not hasattr(self, "crack_tracks"):
                self.crack_tracks = {}

            if hasattr(self, "current_crack_id") and self.current_crack_id is not None:
                crack_id = int(self.current_crack_id)
            else:
                # Fallback allocator if someone calls edge_tracking() ad-hoc
                ann = self.annotation.get("annotations", {})
                ac = ann.get("atomic_cracks", {})
                used = {int(k) for k in ac.keys() if str(k).isdigit()}
                used |= set(int(k) for k in self.crack_tracks.keys())
                crack_id = (max(used) + 1) if used else 0
                self.current_crack_id = crack_id

            print(f"Using crack id {self.current_crack_id} in edge_tracking")

            self.crack_tracks[crack_id] = [track_e1[:, 0], track_e1[:, 1]]
            self.track_e1 = [track_e1[:, 0], track_e1[:, 1]]
            self.track_e2 = [track_e2[:, 0], track_e2[:, 1]]

            # --- Store both crop and full-image normal edges ---
            if not hasattr(self, "normal_edge_points"):
                self.normal_edge_points = {}
            if not hasattr(self, "normal_edge_points_full"):
                self.normal_edge_points_full = {}

            self.normal_edge_points[crack_id] = normal_edges  # crop coords

            xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
            (e1x, e1y), (e2x, e2y) = normal_edges
            e1_global = np.stack([e1x + xmin, e1y + ymin], axis=1)
            e2_global = np.stack([e2x + xmin, e2y + ymin], axis=1)
            self.normal_edge_points_full[crack_id] = {
                "edge1": e1_global.tolist(),
                "edge2": e2_global.tolist()
            }

            if not hasattr(self, "normal_edge_points_clipped"):
                self.normal_edge_points_clipped = {}
            self.normal_edge_points_clipped[crack_id] = normal_edges_clipped

            # --- Draw crop tracks in lower-left panel ---
            pts1 = np.array([track_e1[:, 0], track_e1[:, 1]]).T.reshape((-1, 1, 2)).astype(np.int32)
            pts2 = np.array([track_e2[:, 0], track_e2[:, 1]]).T.reshape((-1, 1, 2)).astype(np.int32)
            im = self.image_crop.astype(np.uint8)
            im = cv2.polylines(im, [pts1], False, (0, 255, 0), w)
            im = cv2.polylines(im, [pts2], False, (0, 255, 0), w)
            qimage = QImage(im, im.shape[1], im.shape[0], im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.edge_tracks_display.width(), self.edge_tracks_display.height(),
                                        Qt.KeepAspectRatio, Qt.FastTransformation)
            self.edge_tracks_display.setPixmap(scaled_pixmap)

            # --- NEW: Show all cracks' masks in the right-hand Segmentation panel ---
            full_mask_display = np.zeros(self.image.shape[:2], dtype=np.uint8)
            ann = self.annotation.get("annotations", {})
            atomic_cracks = ann.get("atomic_cracks", {})
            for crack in atomic_cracks.values():
                mc = crack.get("mask_crop")
                bb = crack.get("mask_bbox")
                if mc is not None and bb is not None:
                    crop = np.array(mc, dtype=np.uint8)
                    x, y, w_box, h_box = [int(v) for v in bb]
                    x2, y2 = min(x + w_box, self.image.shape[1]), min(y + h_box, self.image.shape[0])
                    w_eff, h_eff = max(0, x2 - x), max(0, y2 - y)
                    if h_eff > 0 and w_eff > 0:
                        crop = (crop > 0).astype(np.uint8)[:h_eff, :w_eff]
                        full_mask_display[y:y + h_eff, x:x + w_eff] |= crop

            # Overlay mask boundaries
            from skimage.segmentation import mark_boundaries
            display_im = (mark_boundaries(self.original_image / 255.0, full_mask_display,
                                        color=(0, 0, 1), background_label=0) * 255).astype(np.uint8)

            qimage = QImage(display_im, display_im.shape[1], display_im.shape[0],
                            display_im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled_pixmap = pixmap.scaled(self.ImageScreen.width(), self.ImageScreen.height(),
                                        Qt.KeepAspectRatio, Qt.FastTransformation)
            self.ImageScreen.setPixmap(scaled_pixmap)

            self.edge_tracks_full_screen_button.setStyleSheet("background-color : lightblue")
            self.save_current_segment_button.setStyleSheet("background-color : lightblue")

        except Exception as e:
            error(e)
            self.edge_tracks_full_screen_button.setStyleSheet("background-color : red")
            self.save_current_segment_button.setStyleSheet("background-color : red")

    from shapely import geometry, ops
    import numpy as np, cv2, os, matplotlib.pyplot as plt

    def save_manual_segment(self):
        """
        Save or erase the drawn manual polyline.

        ADD:
        - Requires overlap with an existing atomic (so we already have a midline).
        - Union mask; rebuild geodesic_edges from the unioned mask boundary; recompute normals.

        ERASE:
        - Subtract from mask; if anything remains, rebuild geodesic_edges from the new mask boundary; recompute normals.
        - If nothing remains, delete crack.

        Always calls self.change_image() to refresh the main UI.
        """
        try:
            if not hasattr(self, "manuall_x") or not hasattr(self, "manuall_y"):
                error("No manual polyline to save/erase.")
                return
            if len(self.manuall_x) < 2 or len(self.manuall_y) < 2:
                error("Manual polyline too short.")
                return

            poly = np.column_stack([self.manuall_x, self.manuall_y]).astype(float)

            ann = self.annotation.setdefault("annotations", {})
            atomic = ann.setdefault("atomic_cracks", {})
            combined = ann.setdefault("combined_cracks", {})

            H, W = self.original_image.shape[:2]
            mode = getattr(self, "pending_mode", "add")

            def rebuild_edges_from_mask(full_mask, crack):
                cnts, _ = cv2.findContours((full_mask > 0).astype(np.uint8),
                                        cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)
                if not cnts:
                    return None, None, None
                cnt = max(cnts, key=cv2.contourArea)
                ring = cnt[:, 0, :].astype(float)
                if ring.shape[0] < 4:
                    return None, None, None
                if not (ring[0] == ring[-1]).all():
                    ring = np.vstack([ring, ring[0]])

                m = np.asarray(crack.get("midline", []), float)
                if m.ndim != 2 or m.shape[0] < 2 or m.shape[1] != 2:
                    return None, None, None
                mid_x, mid_y = m[:, 0], m[:, 1]
                start, end = m[0], m[-1]

                d0 = np.sum((ring - start) ** 2, axis=1)
                d1 = np.sum((ring - end) ** 2, axis=1)
                i0, i1 = int(np.argmin(d0)), int(np.argmin(d1))

                if i0 <= i1:
                    path1 = ring[i0:i1 + 1]
                    path2 = np.vstack([ring[i1:], ring[:i0 + 1]])
                else:
                    path1 = np.vstack([ring[i0:], ring[:i1 + 1]])
                    path2 = ring[i1:i0 + 1]

                e1, e2 = np.array(path1, float), np.array(path2, float)
                e1x, e1y, e2x, e2y = ct.segmentation.find_normal_pair(mid_x, mid_y, e1, e2)
                normals = {
                    "edge1": [e1x.tolist(), e1y.tolist()],
                    "edge2": [e2x.tolist(), e2y.tolist()]
                }
                return e1, e2, normals

            def save_debug_plot(crack_id, crack_type, crack, e1, e2, normals):
                import matplotlib.pyplot as plt, time

                m = np.asarray(crack.get("midline", []), float)
                if m.ndim != 2 or m.shape[0] < 2:
                    return
                mid_x, mid_y = m[:, 0], m[:, 1]
                e1x, e1y = np.array(normals["edge1"][0]), np.array(normals["edge1"][1])
                e2x, e2y = np.array(normals["edge2"][0]), np.array(normals["edge2"][1])

                fig, ax = plt.subplots(figsize=(8, 6))
                ax.imshow(self.original_image)
                ax.plot(mid_x, mid_y, 'g-', lw=1, label="midline")
                ax.plot(e1[:, 0], e1[:, 1], 'r-', lw=1, label="edge1")
                ax.plot(e2[:, 0], e2[:, 1], 'b-', lw=1, label="edge2")

                step = max(1, len(mid_x) // 40)
                for i in range(0, len(mid_x), step):
                    if np.isfinite(e1x[i]) and np.isfinite(e2x[i]):
                        ax.plot([mid_x[i], e1x[i]], [mid_y[i], e1y[i]], 'c-', lw=0.8)
                        ax.plot([mid_x[i], e2x[i]], [mid_y[i], e2y[i]], 'm-', lw=0.8)

                ax.set_title(f"{crack_type.capitalize()} crack {crack_id}")
                ax.legend()

                all_x = np.concatenate([mid_x, e1[:, 0], e2[:, 0]])
                all_y = np.concatenate([mid_y, e1[:, 1], e2[:, 1]])
                margin = 20
                ax.set_xlim(max(0, all_x.min() - margin), min(W, all_x.max() + margin))
                ax.set_ylim(min(H, all_y.max() + margin), max(0, all_y.min() - margin))

                save_dir = os.path.join(self.save_folder, "debug_outputs")
                os.makedirs(save_dir, exist_ok=True)
                base_name = os.path.splitext(os.path.basename(self.name))[0]
                ts = int(time.time() * 1000)
                fname = os.path.join(save_dir, f"{base_name}_{crack_type}_{crack_id}_manual.png")
                plt.savefig(fname, dpi=250)
                plt.close(fig)
                print(f"[DEBUG] Saved debug plot → {fname}")

            # ERASE MODE
            if mode == "erase":
                erase_mask = np.zeros((H, W), np.uint8)
                poly_pts = poly.astype(np.int32).reshape((-1, 1, 2))
                cv2.fillPoly(erase_mask, [poly_pts], 255)

                to_delete, changed = [], []
                for cid, crack in list(atomic.items()):
                    mc, bb = crack.get("mask_crop"), crack.get("mask_bbox")
                    if mc is None or bb is None or not len(mc):
                        full_old = np.zeros((H, W), np.uint8)
                    else:
                        crop = np.array(mc, dtype=np.uint8)
                        x0, y0, w, h = [int(v) for v in bb]
                        x1, y1 = min(x0 + w, W), min(y0 + h, H)
                        full_old = np.zeros((H, W), np.uint8)
                        full_old[y0:y1, x0:x1] = crop[:y1 - y0, :x1 - x0]

                    full_new = cv2.bitwise_and(full_old, cv2.bitwise_not(erase_mask))

                    if np.any(full_new):
                        ys, xs = np.where(full_new > 0)
                        x0, x1, y0, y1 = xs.min(), xs.max() + 1, ys.min(), ys.max() + 1
                        crop = full_new[y0:y1, x0:x1]
                        crack["mask_crop"] = crop.tolist()
                        crack["mask_bbox"] = [int(x0), int(y0), int(x1 - x0), int(y1 - y0)]

                        e1, e2, normals = rebuild_edges_from_mask(full_new, crack)
                        if e1 is not None:
                            crack["geodesic_edges"] = {"edge1": e1.tolist(), "edge2": e2.tolist()}
                            crack["normal_edge_points"] = normals
                            save_debug_plot(cid, "atomic", crack, e1, e2, normals)
                            changed.append(cid)
                    else:
                        to_delete.append(cid)

                for cid in to_delete:
                    del atomic[cid]

                # if exactly one atomic was changed, check its combined membership
                if len(changed) == 1:
                    changed_id = changed[0]
                    for cmb_id, cmb in combined.items():
                        if changed_id in cmb.get("members", []):
                            combined[cmb_id] = self._build_combined_crack(cmb["members"])
                            # build mask for that combined
                            full_mask = np.zeros((H, W), np.uint8)
                            for member_id in cmb["members"]:
                                mc, bb = atomic[member_id]["mask_crop"], atomic[member_id]["mask_bbox"]
                                crop = np.array(mc, dtype=np.uint8)
                                x0, y0, w, h = [int(v) for v in bb]
                                x1, y1 = min(x0 + w, W), min(y0 + h, H)
                                full_mask[y0:y1, x0:x1] |= crop[:y1-y0, :x1-x0]
                            e1, e2, normals = rebuild_edges_from_mask(full_mask, atomic[changed_id])
                            if e1 is not None:
                                save_debug_plot(cmb_id, "combined", atomic[changed_id], e1, e2, normals)
                            break

                self.save_annotation()

            # ADD MODE
            else:
                target_id, target_crack = None, None
                poly_mask = np.zeros((H, W), np.uint8)
                cv2.fillPoly(poly_mask, [poly.astype(np.int32).reshape((-1, 1, 2))], 255)

                for cid, crack in atomic.items():
                    mc, bb = crack.get("mask_crop"), crack.get("mask_bbox")
                    if mc is None or bb is None or not len(mc):
                        continue
                    crop = np.array(mc, dtype=np.uint8)
                    x0, y0, w, h = [int(v) for v in bb]
                    x1, y1 = min(x0 + w, W), min(y0 + h, H)
                    full_old = np.zeros((H, W), np.uint8)
                    full_old[y0:y1, x0:x1] = crop[:y1 - y0, :x1 - x0]

                    if np.any(cv2.bitwise_and(full_old, poly_mask)):
                        target_id, target_crack = cid, crack
                        break

                if target_crack is None:
                    return

                mc, bb = target_crack.get("mask_crop"), target_crack.get("mask_bbox")
                if mc is None or bb is None or not len(mc):
                    full_old = np.zeros((H, W), np.uint8)
                else:
                    crop = np.array(mc, dtype=np.uint8)
                    x0, y0, w, h = [int(v) for v in bb]
                    x1, y1 = min(x0 + w, W), min(y0 + h, H)
                    full_old = np.zeros((H, W), np.uint8)
                    full_old[y0:y1, x0:x1] = crop[:y1 - y0, :x1 - x0]

                full_new = cv2.bitwise_or(full_old, poly_mask)
                ys, xs = np.where(full_new > 0)
                if len(xs) and len(ys):
                    x0, x1, y0, y1 = xs.min(), xs.max() + 1, ys.min(), ys.max() + 1
                    crop = full_new[y0:y1, x0:x1]
                    target_crack["mask_crop"] = crop.tolist()
                    target_crack["mask_bbox"] = [int(x0), int(y0), int(x1 - x0), int(y1 - y0)]

                e1, e2, normals = rebuild_edges_from_mask(full_new, target_crack)
                if e1 is not None:
                    target_crack["geodesic_edges"] = {"edge1": e1.tolist(), "edge2": e2.tolist()}
                    target_crack["normal_edge_points"] = normals
                    save_debug_plot(target_id, "atomic", target_crack, e1, e2, normals)

                # only one combined if any
                for cmb_id, cmb in combined.items():
                    if target_id in cmb.get("members", []):
                        combined[cmb_id] = self._build_combined_crack(cmb["members"])
                        full_mask = np.zeros((H, W), np.uint8)
                        for member_id in cmb["members"]:
                            mc, bb = atomic[member_id]["mask_crop"], atomic[member_id]["mask_bbox"]
                            crop = np.array(mc, dtype=np.uint8)
                            x0, y0, w, h = [int(v) for v in bb]
                            x1, y1 = min(x0 + w, W), min(y0 + h, H)
                            full_mask[y0:y1, x0:x1] |= crop[:y1-y0, :x1-x0]
                        e1, e2, normals = rebuild_edges_from_mask(full_mask, target_crack)
                        if e1 is not None:
                            save_debug_plot(cmb_id, "combined", target_crack, e1, e2, normals)
                        break

                self.save_annotation()

            # refresh manual preview screen
            im = self.image.astype(np.uint8).copy()
            im = self.draw_existing_cracks(im)
            qimage = QImage(im, im.shape[1], im.shape[0],
                            im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled = pixmap.scaled(
                self.manual_segment_screen.width(),
                self.manual_segment_screen.height(),
                Qt.KeepAspectRatio,
                Qt.FastTransformation
            )
            self.manual_segment_screen.setPixmap(scaled)

            self.change_image()

            if hasattr(self, "manuall_x"): del self.manuall_x
            if hasattr(self, "manuall_y"): del self.manuall_y

        except Exception as e:
            import traceback; traceback.print_exc()
            error(e)

    def save_current_segment(self):
        try:
            xmin, ymin, xmax, ymax = [int(round(v)) for v in self.active_bbox]
            print(f"[DEBUG] save_current_segment bbox: xmin={xmin}, ymin={ymin}, xmax={xmax}, ymax={ymax}")

            # Build crop mask from the two edges (in crop coords)
            print(f"[DEBUG] track_e1 shape={np.shape(self.track_e1)}, track_e2 shape={np.shape(self.track_e2)}")
            print(f"[DEBUG] track_e1 sample (y,x): {list(zip(self.track_e1[0][:5], self.track_e1[1][:5]))}")
            print(f"[DEBUG] track_e2 sample (y,x): {list(zip(self.track_e2[0][:5], self.track_e2[1][:5]))}")

            edge_x_crop = np.concatenate((self.track_e1[1][::-1], self.track_e2[1]))
            edge_y_crop = np.concatenate((self.track_e1[0][::-1], self.track_e2[0]))
            print(f"[DEBUG] edge_x_crop[:5]={edge_x_crop[:5]}, edge_y_crop[:5]={edge_y_crop[:5]}")

            mask_crop = ct.segmentation.create_mask(self.image_crop, edge_y_crop, edge_x_crop).astype(np.uint8)
            h, w = mask_crop.shape[:2]
            print(f"[DEBUG] mask_crop shape={mask_crop.shape}, nonzero={int((mask_crop>0).sum())}")

            src = getattr(self, "current_source", "auto")
            track_arr = np.array(self.adjusted_track, dtype=float)
            print(f"[DEBUG] adjusted_track shape={track_arr.shape}, sample={track_arr[:, :5]}")

            # Convert midline to full-image coords
            midline_coords = [
                [int(track_arr[1][i] + xmin), int(track_arr[0][i] + ymin)]
                for i in range(track_arr.shape[1])
            ]
            print(f"[DEBUG] midline first={midline_coords[0]}, last={midline_coords[-1]}")

            ann = self.annotation.setdefault("annotations", {})
            atomic_cracks = ann.setdefault("atomic_cracks", {})

            # Add full, unclipped normal-edge points
            normal_edges = getattr(self, "normal_edge_points", {}).get(self.current_crack_id)
            normal_edges_full = None
            if normal_edges is not None:
                (e1x, e1y), (e2x, e2y) = normal_edges
                print(f"[DEBUG] normal_edges e1 first={(e1x[0], e1y[0])}, e2 first={(e2x[0], e2y[0])}")
                e1_global = np.stack([e1x + xmin, e1y + ymin], axis=1)
                e2_global = np.stack([e2x + xmin, e2y + ymin], axis=1)
                normal_edges_full = {"edge1": e1_global.tolist(), "edge2": e2_global.tolist()}

            atomic_cracks[str(self.current_crack_id)] = {
                "source": src,
                "midline": midline_coords,
                "geodesic_edges": {
                    "edge1": [[int(self.track_e1[0][i] + xmin), int(self.track_e1[1][i] + ymin)]
                            for i in range(len(self.track_e1[0]))],
                    "edge2": [[int(self.track_e2[0][i] + xmin), int(self.track_e2[1][i] + ymin)]
                            for i in range(len(self.track_e2[0]))]
                },
                "normal_edge_points": normal_edges_full,
                "mask_crop": mask_crop.tolist(),
                "mask_bbox": [int(xmin), int(ymin), int(w), int(h)],
                "user_points": getattr(self, "user_points", []),
                "user_connections": getattr(self, "user_connections", [])
            }
            print(f"[DEBUG] atomic_cracks keys now: {list(atomic_cracks.keys())}")

            # ---- NEW DEBUG VISUALIZATION (full-image overlay) ----
            '''import matplotlib.pyplot as plt
            fig, ax = plt.subplots(figsize=(12,8))
            ax.imshow(self.original_image)
            ax.plot([p[0] for p in midline_coords], [p[1] for p in midline_coords],
                    'g-', lw=1, label="Saved Midline")
            for edge in ["edge1", "edge2"]:
                exy = atomic_cracks[str(self.current_crack_id)]["geodesic_edges"][edge]
                ax.plot([p[0] for p in exy], [p[1] for p in exy],
                        '-' if edge=="edge1" else '--',
                        lw=1, label=f"Saved {edge}")
            ax.legend()
            ax.set_title(f"DEBUG: Saved crack {self.current_crack_id} (full-image overlay)")
            plt.show()'''
            # ------------------------------------------------------

            self.use_masks = True
            self.save_annotation()

        except Exception as e:
            error(e)
    
    def select_end_points_manmidlines(self):
        if not hasattr(self, "original_image") or self.original_image is None:
            error("No original image found.")
            return
        
        if not hasattr(self, "annotation") or self.annotation is None:
            error("No annotation data found.")
            return

        from PyQt5.QtWidgets import (
            QDialog, QVBoxLayout, QHBoxLayout, QPushButton,
            QSizePolicy, QApplication, QMessageBox, QScrollArea, QLabel
        )

        boxes = self.get_all_bounding_boxes()

        readonly_midlines = {}
        readonly_connections = []
        existing_midlines = {}

        initial_points = list(getattr(self, "user_points", []) or [])
        initial_conns = list(getattr(self, "user_connections", []) or [])
        point_index_map = {tuple(pt): idx for idx, pt in enumerate(initial_points)}

        def ensure_point(pt):
            if tuple(pt) not in point_index_map:
                point_index_map[tuple(pt)] = len(initial_points)
                initial_points.append(pt)
            return point_index_map[tuple(pt)]

        if "annotations" in self.annotation:
            ann = self.annotation["annotations"]

            ann_midlines = ann.get("midlines", {})
            for k_str, pts in ann_midlines.items():
                try:
                    i1, i2 = map(int, k_str.split("_"))
                    if i1 != i2:  # Prevent self-midlines here
                        poly = [tuple(map(float, xy)) for xy in pts]
                        existing_midlines[(min(i1, i2), max(i1, i2))] = poly
                except Exception as e:
                    print(f"[WARN] Failed to parse manual midline {k_str}: {e}")

            for cid, crack in ann.get("atomic_cracks", {}).items():
                if hasattr(self, "current_crack_id") and str(cid) == str(self.current_crack_id):
                    continue

                src = crack.get("source", "auto")
                up = crack.get("user_points", [])
                if len(up) == 2:
                    p1, p2 = tuple(up[0]), tuple(up[1])
                else:
                    ml = crack.get("midline", [])
                    if len(ml) >= 2:
                        p1, p2 = tuple(ml[0]), tuple(ml[-1])
                    else:
                        continue

                idx1 = ensure_point(p1)
                idx2 = ensure_point(p2)

                if idx1 == idx2:
                    continue  # Prevent self-midlines here too

                if src in ("manual", "manual_poly"):
                    poly = crack.get("midline", [])
                    if poly:
                        readonly_midlines[(idx1, idx2)] = [tuple(map(float, xy)) for xy in poly]
                else:
                    readonly_connections.append((p1, p2))

        for (i1, i2), poly in existing_midlines.items():
            start_idx = ensure_point(poly[0])
            end_idx = ensure_point(poly[-1])
            if start_idx != end_idx:
                readonly_midlines[(start_idx, end_idx)] = poly

        readonly_conn_idx = []
        for p1, p2 in readonly_connections:
            idx1 = ensure_point(p1)
            idx2 = ensure_point(p2)
            if idx1 != idx2:
                readonly_conn_idx.append((min(idx1, idx2), max(idx1, idx2)))

        annot = CrackAnnotator(
            image=self.original_image,
            boxes=boxes,
            initial_points=initial_points,
            initial_connections=initial_conns,
            initial_midlines={},
        )

        annot.readonly_midlines = readonly_midlines
        annot.readonly_connections = readonly_conn_idx

        # Also enforce at the widget level:
        # Wrap the original mousePressEvent to prevent bad start/finish overlaps
        # Also enforce at the widget level:
        orig_mousePressEvent = annot.mousePressEvent

        def guarded_mousePressEvent(ev):
            p = annot._to_image_coords(ev.pos())
            point_i = annot._find_point_at(p)

            # Gather extra debug state
            last_pt = annot.polyline[-1] if annot.polyline else None
            last_two_pts = annot.polyline[-2:] if len(annot.polyline) >= 2 else []
            conn_key = None
            if annot._is_drawing and point_i is not None and point_i != annot._start_idx:
                conn_key = annot._sorted(annot._start_idx, point_i)
            exists_midline = conn_key in annot.midlines if conn_key else None
            exists_conn = conn_key in annot.connections if conn_key else None
            exists_readonly_conn = conn_key in annot.readonly_connections if conn_key else None
            exists_readonly_mid = conn_key in annot.readonly_midlines if conn_key else None

            start_pt = annot.points[annot._start_idx] if annot._start_idx is not None and annot._start_idx < len(annot.points) else None

            print(
                f"[GUARDED_PRESS] btn={ev.button()} at {p} | "
                f"point_i={point_i}, start_idx={annot._start_idx}, start_pt={start_pt} | "
                f"_is_drawing={annot._is_drawing}, polyline_mode={annot.polyline_mode} | "
                f"polyline_len={len(annot.polyline)}, last_pt={last_pt}, last_two_pts={last_two_pts} | "
                f"_just_committed_midline={getattr(annot, '_just_committed_midline', False)}, "
                f"_last_polyline_end_idx={getattr(annot, '_last_polyline_end_idx', None)} | "
                f"conn_key={conn_key}, exists_midline={exists_midline}, exists_conn={exists_conn}, "
                f"exists_readonly_conn={exists_readonly_conn}, exists_readonly_mid={exists_readonly_mid}"
            )

            # If not in polyline mode — just pass through immediately
            if not annot.polyline_mode:
                print("[GUARDED_PRESS] Not in polyline_mode — passing through")
                orig_mousePressEvent(ev)
                return

            # --- Prevent immediate restart after a commit on either endpoint of last line ---
            if getattr(annot, "_just_committed_midline", False):
                last_end = getattr(annot, "_last_polyline_end_idx", None)
                last_start = getattr(annot, "_last_polyline_start_idx", None)
                if point_i is not None and point_i in (last_end, last_start):
                    print(
                        f"[GUARDED_PRESS] blocked: click is on endpoint {point_i} of last committed line "
                        f"({last_start}, {last_end}) — skipping to avoid rubberband"
                    )
                    annot._just_committed_midline = False
                    return
                # Reset flag if click is elsewhere
                annot._just_committed_midline = False

            # Polyline mode but NOT drawing yet
            if not annot._is_drawing:
                if point_i is not None and annot._start_idx == point_i:
                    print("[GUARDED_PRESS] blocked: start on same point as last start")
                    return
                print("[GUARDED_PRESS] passing to orig to START polyline")
                orig_mousePressEvent(ev)
                return

            # Polyline mode AND currently drawing
            if point_i is not None and point_i != annot._start_idx:
                print(f"[GUARDED_PRESS] finishing midline via click on endpoint {point_i}, key={conn_key}")
            elif point_i is None:
                print("[GUARDED_PRESS] adding freehand point via click")
            else:
                print("[GUARDED_PRESS] ignored click (same as start idx)")

            orig_mousePressEvent(ev)

        annot.mousePressEvent = guarded_mousePressEvent

        annot.setSizePolicy(QtWidgets.QSizePolicy.Ignored, QtWidgets.QSizePolicy.Ignored)

        dlg = QDialog(self.MainWindow)
        dlg.setWindowTitle("Endpoints, Connections & Manual Midlines")
        dlg.setWindowModality(Qt.ApplicationModal)
        dlg.setWindowFlags(dlg.windowFlags() | Qt.WindowMaximizeButtonHint)
        layout = QVBoxLayout(dlg)

        mode_btn = QPushButton("Switch to Connection Mode")
        mode_btn.setCheckable(True)
        layout.addWidget(mode_btn)

        manual_btn = QPushButton("Manual Midlines: OFF")
        manual_btn.setCheckable(True)
        manual_btn.setVisible(False)
        layout.addWidget(manual_btn)

        hint = QLabel(
            "Editable: Auto/Manual in black/light-blue.     Read-only: Auto/Manual cracks in gray/beige — cant delete in editor, must delete segment in Delete Segmentations.\n"
            "Click unconnected point in Connection Mode to create new point.        Hover and click in respective mode to delete.        Mousewheel/2-finger swipe = zoom in/out.\n"
            "Manual: Left-hold on starting point → draw → finish on a different endpoint.       Backspace/Z or Right-hold for fast/slow deletion.       Shimmy: zoom in toward direction, zoom out slightly to move; image may distort until 1.0 scale."
        )
        layout.addWidget(hint)

        scroll = QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setWidget(annot)
        layout.addWidget(scroll, 1)

        btn_row = QHBoxLayout()
        btn_done, btn_cancel = QPushButton("Done"), QPushButton("Cancel")
        btn_row.addWidget(btn_done)
        btn_row.addWidget(btn_cancel)
        layout.addLayout(btn_row)

        def all_points_in_boxes():
            def in_any(pt):
                x, y = pt
                for xmin, ymin, xmax, ymax in boxes:
                    if xmin <= x <= xmax and ymin <= y <= ymax:
                        return True
                return False

            readonly_point_idxs = set()
            for (i1, i2) in annot.readonly_connections:
                readonly_point_idxs.update([i1, i2])
            for (i1, i2) in annot.readonly_midlines.keys():
                readonly_point_idxs.update([i1, i2])

            bad = [
                pt for idx, pt in enumerate(annot.points)
                if idx not in readonly_point_idxs and not in_any(pt)
            ]
            return (len(bad) == 0, bad)

        def confirm_discard():
            mb = QMessageBox(dlg)
            mb.setIcon(QMessageBox.Warning)
            mb.setWindowTitle("Discard current midline?")
            mb.setText("You're in the middle of drawing a midline. Discard it?")
            mb.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
            return mb.exec_() == QMessageBox.Yes

        def update_controls_visibility():
            if annot.polyline_mode:
                mode_btn.setVisible(False)
                manual_btn.setVisible(True)
                manual_btn.setText("Manual Midlines: ON")
                manual_btn.setStyleSheet("background:#79d2e6;")
            else:
                mode_btn.setVisible(True)
                if annot.connection_mode:
                    mode_btn.setText("Switch to Point Mode")
                    mode_btn.setStyleSheet("background:#97e297;")
                else:
                    mode_btn.setText("Switch to Connection Mode")
                    mode_btn.setStyleSheet("background:#e2c297;")
                manual_btn.setVisible(annot.connection_mode and (not annot.all_pairs_saturated()))
                manual_btn.setText("Manual Midlines: OFF")
                manual_btn.setStyleSheet("")

        mode_btn.clicked.connect(lambda: (annot.toggle_mode(), update_controls_visibility()))
        manual_btn.clicked.connect(lambda checked: (
            annot.set_mode_polyline(checked, confirm_cb=confirm_discard),
            update_controls_visibility()
        ))
        update_controls_visibility()
            
        def on_done():
            if annot.polyline_mode and annot._is_drawing:
                if not confirm_discard():
                    return
                annot.set_mode_polyline(False)

            ok, bad = all_points_in_boxes()
            if not ok:
                # Format the bad points as a readable string
                bad_str = "\n".join([f"({x:.1f}, {y:.1f})" for (x, y) in bad])
                QMessageBox.warning(
                    dlg,
                    "Points outside boxes",
                    f"The following points are outside all bounding boxes:\n{bad_str}"
                )
                return

            # Validate midlines are fully inside one bounding box
            for (i1, i2), poly in annot.midlines.items():
                if i1 == i2:
                    continue

                try:
                    sx, sy = annot.points[i1]
                    ex, ey = annot.points[i2]
                except Exception:
                    continue

                def point_box(x, y):
                    for bi, (xmin, ymin, xmax, ymax) in enumerate(boxes):
                        if xmin <= x <= xmax and ymin <= y <= ymax:
                            return bi
                    return None

                b1 = point_box(float(sx), float(sy))
                b2 = point_box(float(ex), float(ey))

                if b1 is None or b2 is None or b1 != b2:
                    QMessageBox.warning(dlg, "Invalid midline",
                        "A manual midline crosses or spans multiple boxes. Please fix before continuing.")
                    return

                xmin, ymin, xmax, ymax = boxes[b1]
                for (x, y) in poly:
                    if not (xmin <= float(x) <= xmax and ymin <= float(y) <= ymax):
                        QMessageBox.warning(dlg, "Invalid midline",
                            "A manual midline has points outside its box. Please fix before continuing.")
                        return

            self.user_points = annot.points
            self.user_connections = [c for c in annot.connections if c not in annot.readonly_connections]

            self.endpoint_pairs = [
                (self.user_points[i1], self.user_points[i2])
                for (i1, i2) in self.user_connections
            ]

            self.manual_endpoint_pairs = []
            for (i1, i2), poly in annot.midlines.items():
                if i1 != i2:  # Final check to prevent self-midline
                    self.manual_endpoint_pairs.append((self.user_points[i1], self.user_points[i2]))

            self.manual_midlines_tmp = {
                f"{i1}_{i2}": [[float(x), float(y)] for (x, y) in poly]
                for (i1, i2), poly in annot.midlines.items() if i1 != i2
            }

            if hasattr(self, "current_crack_id"):
                crack_id_str = str(self.current_crack_id)
                crack_entry = self.annotation.get("annotations", {}).get("atomic_cracks", {}).setdefault(crack_id_str, {})
                crack_entry["user_points"] = list(self.user_points)
                crack_entry["user_connections"] = list(self.user_connections)

            dlg.accept()

        btn_done.clicked.connect(on_done)
        btn_cancel.clicked.connect(lambda: dlg.reject())

        dlg.showMaximized()
        QApplication.processEvents()
        if dlg.exec_() != QDialog.Accepted:
            return

        print(f"Points: {self.user_points}")
        print(f"Connections: {self.user_connections}")
        print(f"Endpoint pairs: {self.endpoint_pairs}")
        print(f"Manual endpoint pairs: {getattr(self, 'manual_endpoint_pairs', [])}")
        print(f"Midlines saved: {len(self.manual_midlines_tmp)}")
        self.update_image_crop_button.setStyleSheet("background-color: lightblue")
        self._debug_print_atomic_cracks("select_end_points_manmidlines AFTER ACCEPT")
        self.all_selected_points = list(self.user_points)
        
    def run_pipeline(self, multirun=False):
        import gc, json
        import numpy as np
        from PyQt5.QtWidgets import QMessageBox
        from time import time

        # ---- helpers ---------------------------------------------------------
        def _ensure_ann():
            # make sure base structure exists
            if not hasattr(self, "annotation") or not isinstance(self.annotation, dict):
                self.annotation = {}
            ann = self.annotation.setdefault("annotations", {})
            ann.setdefault("atomic_cracks", {})
            ann.setdefault("combined_cracks", {})
            # scrub stray non-numeric keys
            bad_keys = [k for k in ann["atomic_cracks"].keys() if not str(k).isdigit()]
            for bk in bad_keys:
                ann["atomic_cracks"].pop(bk, None)
            return ann

        def _next_crack_id_str():
            """
            Return the lowest non-negative id that is NOT used in saved atomic_cracks.
            This ignores any in-memory caches so deleted ids are reused.
            """
            ann = self.annotation.get("annotations", {})
            ac = ann.get("atomic_cracks", {})
            used = sorted(int(k) for k in ac.keys() if str(k).isdigit())
            nxt = 0
            for k in used:
                if k == nxt:
                    nxt += 1
                elif k > nxt:
                    break
            return str(nxt)

        # ---- start -----------------------------------------------------------
        gc.collect()
        print("✅ GPU memory freed from CuPy pool")
        print("Running midline pipeline (auto + manual)...")

        # reset scratch between runs so ids don't leak/inflate
        self.current_crack_id = None
        self.crack_tracks = {}        # in-memory geodesic paths per id (scratch only)

        ann = _ensure_ann()
        ac_store = ann["atomic_cracks"]

        boxes = self.get_all_bounding_boxes()
        print(f"Loaded {len(boxes)} bounding boxes: {boxes}")
        if not boxes:
            QMessageBox.critical(None, "No Bounding Boxes",
                "Please draw at least one bounding box before running the pipeline.")
            return

        if not multirun:
            # Let the user pick points/connections/midlines
            self.endpoint_pairs = None
            self.user_connections = None
            self.user_points = None
            self.manual_endpoint_pairs = None
            self.all_selected_points = None  # reset before each run
            print("Calling select_end_points_manmidlines()...")
            self.select_end_points_manmidlines()

        # Merge auto + manual endpoint pairs (global, from annotator)
        all_pairs = []
        if getattr(self, "endpoint_pairs", None):
            print(f"Auto endpoint_pairs: {self.endpoint_pairs}")
            all_pairs.extend([(p, "auto") for p in self.endpoint_pairs])

        if getattr(self, "manual_endpoint_pairs", None):
            print(f"Manual endpoint_pairs: {self.manual_endpoint_pairs}")
            all_pairs.extend([(p, "manual") for p in self.manual_endpoint_pairs])

        if not all_pairs:
            QMessageBox.critical(
                None, "No Endpoint Pairs",
                "No endpoint pairs selected!\n\nPlease use 'Select Endpoints' and create at least one connection or manual midline before running the pipeline."
            )
            return

        # Group by bbox (so OS/cost is reused per box)
        box_to_pairs = {}
        for (pair, src) in all_pairs:
            candidates = []
            for bbox in boxes:
                xmin, ymin, xmax, ymax = bbox
                p0, p1 = pair
                if (xmin <= p0[0] <= xmax and ymin <= p0[1] <= ymax and
                    xmin <= p1[0] <= xmax and ymin <= p1[1] <= ymax):
                    area = abs((xmax - xmin) * (ymax - ymin))
                    candidates.append((area, bbox))
            if candidates:
                _, chosen_bbox = min(candidates, key=lambda x: x[0])
                key = tuple(chosen_bbox)
                box_to_pairs.setdefault(key, []).append((pair, src))

        errors = []

        # Make sure we don't blow away memory of previous masks
        if not hasattr(self, "mask"):
            self.mask = []

        for bbox_key, pairs in box_to_pairs.items():
            xmin, ymin, xmax, ymax = bbox_key
            print(f"\n=== Processing bbox {bbox_key} ===")
            print(f"Pairs in this box: {pairs}")

            try:
                # Precompute OS/cost once per box for auto pairs
                auto_pairs = [p for p, s in pairs if s == "auto"]
                if auto_pairs:
                    first_pair = auto_pairs[0]
                    print(f"Precomputing OS/cost for auto pair {first_pair}")
                    self.pts = [np.array(first_pair[0]), np.array(first_pair[1])]
                    self.end_points = self.pts
                    self.active_bbox = list(bbox_key)
                    self.update_image_crop()
                    if getattr(self, "skip_current_segment", False):
                        continue
                    print("os (once per box)")
                    t0 = time(); self.update_os(); print(f"os time: {time()-t0:.2f}s")
                    print("cost (once per box)")
                    t0 = time(); self.update_cost(); print(f"cost time: {time()-t0:.2f}s")

                # Process each pair -> one atomic crack per pair
                for (p0, p1), src in pairs:
                    try:
                        self.active_bbox = list(bbox_key)
                        print(f"\n--- Processing pair {(p0, p1)} (source={src}) ---")

                        # Per-crack, pair-local endpoints for saving
                        pair_user_points = [tuple(p0), tuple(p1)]
                        pair_user_connections = [[0, 1]]  # exactly one connection per crack

                        if src in ("manual", "manual_poly"):
                            # For manual, we reuse the drawn polyline as midline (full-image coords)
                            manual_midlines_dict = getattr(self, "manual_midlines_tmp", {})
                            found_key = None

                            # Durable copy of selection points from earlier
                            all_points = getattr(self, "all_selected_points", None)
                            if all_points is None:
                                all_points = getattr(self, "user_points", [])

                            print("\n[DEBUG] --- Matching manual midline ---")
                            print(f"[DEBUG] manual_midlines_tmp keys at runtime: {list(manual_midlines_dict.keys())}")
                            print(f"[DEBUG] all_points at runtime: {all_points}")
                            print(f"[DEBUG] Trying to match p0={p0}  p1={p1}")

                            # manual_midlines_tmp keys are "i_j" from annotator indices; match geometrically
                            for k, poly in manual_midlines_dict.items():
                                try:
                                    i1, i2 = map(int, k.split("_"))
                                    c_i = tuple(all_points[i1])
                                    c_j = tuple(all_points[i2])
                                    print(f"[DEBUG] Checking key={k}, c_i={c_i}, c_j={c_j}")
                                    if (c_i, c_j) == (p0, p1) or (c_i, c_j) == (p1, p0):
                                        print(f"[DEBUG] Found match for key={k}")
                                        found_key = k
                                        break
                                except Exception as e:
                                    print(f"[DEBUG] Error parsing key={k}: {e}")

                            print(f"[MANUAL] Found key: {found_key}")
                            self.pts = [np.array(p0), np.array(p1)]
                            self.end_points = self.pts
                            self.update_image_crop()
                            if getattr(self, "skip_current_segment", False):
                                continue

                            if found_key:
                                # Convert full-image manual polyline to crop coords and set as self.track
                                poly = np.array(manual_midlines_dict[found_key], dtype=float)  # [[x,y],...]
                                cy = poly[:, 1] - ymin
                                cx = poly[:, 0] - xmin
                                self.track = np.vstack([cy, cx])
                                self.pts_crop = [
                                    np.array(self.pts[0]) - np.array([xmin, ymin]),
                                    np.array(self.pts[1]) - np.array([xmin, ymin])
                                ]
                                downsample = self.downsample_factor_box.value()
                                self.pts_crop_down = [p / downsample for p in self.pts_crop]
                            else:
                                msg = f"No manual polyline found for manual crack {p0}→{p1}"
                                print("ERROR:", msg)
                                errors.append(msg)
                                continue
                        else:
                            # Auto mode
                            self.pts = [np.array(p0), np.array(p1)]
                            self.end_points = self.pts
                            self.pts_crop = [np.array(pt) - np.array([xmin, ymin]) for pt in self.pts]
                            downsample = self.downsample_factor_box.value()
                            self.pts_crop_down = [p / downsample for p in self.pts_crop]
                            t0 = time(); self.midline_tracking(); print(f"    midline tracking time: {time()-t0:.2f}s")

                        # ======= Assign a brand-new crack ID for THIS pair (gap-free) =======
                        new_cid = _next_crack_id_str()
                        self.current_crack_id = int(new_cid)

                        # Geodesic edges & masks for this pair
                        self.current_source = src
                        self.edge_mask()
                        self.edge_tracking()

                        # Pair-local globals so save_current_segment writes them into that crack
                        self.user_points = pair_user_points
                        self.user_connections = pair_user_connections

                        # Save segment (midline + edges + mask + per-crack endpoints)
                        self.save_current_segment()

                        # Clear pair-local globals so next crack doesn't inherit them
                        self.user_points = None
                        self.user_connections = None

                    except Exception as e:
                        errors.append(f"Failed midline for {(p0, p1)}: {e}")
                        continue

            except Exception as e:
                errors.append(f"Failed for bbox {bbox_key}: {e}")
                continue

        # Done with all boxes/pairs
        if errors:
            print("\n".join(errors))
        else:
            print("✔ All endpoint groups processed.")

        # Clear UI temp state (per-run scratch)
        self.endpoint_pairs = None
        self.manual_endpoint_pairs = None

        # Persist JSON
        with open(self.ann_name, 'w') as fp:
            json.dump(self.annotation, fp)
            
        self.auto_combine_segments()

        # Debug print & refresh view
        self._debug_print_atomic_cracks("run_pipeline END")
        self.change_image()
            
    def update_os_cost(self):
        """
        Runs the OS and cost function generation for the current image.
        This is a helper function to quickly generate the OS and cost without running the full pipeline.
        """
        try:
            self.update_image_crop()  # Ensure the crop is set correctly
            self.update_os()
            self.update_cost()
            print("OS and cost function generated successfully.")
        except Exception as e:
            error(e)
            print("Error generating OS or cost function:", e)
            
    def batch_run_pipeline(self):
        """
        Runs the pipeline (full segment generation, clearing endpoints/connections) on EVERY image in the selected folder.
        """
        from PyQt5.QtWidgets import QMessageBox
        
        # Check existence and content
        if not hasattr(self, "image_names") or not self.image_names:
            QMessageBox.warning(self.MainWindow, "Batch Run", "No images loaded. Please select a folder with images first.")
            print("Batch run aborted: no images loaded.")
            return
        
        total = len(self.image_names)
        errors = []
        n_success = 0
        orig_n = self.n

        for idx, fname in enumerate(self.image_names):
            try:
                self.n = idx
                self.change_image()
                # Only run if endpoints and connections are present
                endpoints = getattr(self, "user_points", None)
                connections = getattr(self, "user_connections", None)
                if endpoints and connections:
                    print(f"\n======= Processing image {idx+1}/{total}: {fname} =======")
                    self.run_pipeline(multirun=True)  # Will clear endpoints on success
                    n_success += 1
                    #return
                else:
                    print(f"  [SKIP] No endpoints/connections for this image.")
            except Exception as e:
                errors.append(f"Image {fname}: {e}")

        self.n = orig_n
        self.change_image()
        summary = f"Batch pipeline run complete.\nSuccessful: {n_success}/{total}\n"
        if errors:
            summary += f"\nErrors:\n" + "\n".join(errors)
        print(summary)
        QMessageBox.information(self.MainWindow, "Batch pipeline finished", summary)

    def combine_segments(self):
        """
        Combine multiple cracks (atomic or already-combined) into a new combined crack.
        - If an atomic crack belongs to a combined crack, it is listed under that combined crack instead.
        - Each crack appears only once in the selection list.
        - Requires at least two entries in the list to start combining.
        """
        from PyQt5.QtWidgets import QDialog, QVBoxLayout, QListWidget, QPushButton, QHBoxLayout
        from PyQt5.QtGui import QImage, QPixmap
        from PyQt5.QtCore import Qt
        import numpy as np, cv2

        if not hasattr(self, "annotation") or not isinstance(self.annotation, dict):
            error("No annotation data loaded.")
            return

        ann = self.annotation.setdefault("annotations", {})
        atomic_cracks = ann.setdefault("atomic_cracks", {})
        combined_cracks = ann.setdefault("combined_cracks", {})

        H, W = self.original_image.shape[:2]

        # --- Helpers
        def mask_from_crack(crack):
            mc = crack.get("mask_crop"); bb = crack.get("mask_bbox")
            if mc is not None and bb is not None:
                crop = np.array(mc, dtype=np.uint8)
                x, y, w, h = [int(v) for v in bb]
                x2, y2 = min(x + w, W), min(y + h, H)
                w_eff, h_eff = max(0, x2 - x), max(0, y2 - y)
                if h_eff > 0 and w_eff > 0:
                    crop = (crop > 0).astype(np.uint8)[:h_eff, :w_eff]
                    m = np.zeros((H, W), dtype=np.uint8)
                    m[y:y+h_eff, x:x+w_eff] = crop
                    return m
            full = np.array(crack.get("mask", []), dtype=np.uint8)
            if full.size == H * W and full.shape == (H, W):
                return (full > 0).astype(np.uint8)
            return np.zeros((H, W), dtype=np.uint8)

        def cracks_overlap_or_connect(crackA, crackB):
            # Overlap check
            mA = mask_from_crack(crackA)
            mB = mask_from_crack(crackB)
            if np.any(mA & mB):
                return True
            # User endpoint check
            upA = [tuple(pt) for pt in crackA.get("user_points", [])]
            upB = [tuple(pt) for pt in crackB.get("user_points", [])]
            if set(upA) & set(upB):
                return True
            return False

        def cracks_all_connected(cracks):
            """Ensure all cracks form one connected component by overlap/endpoints."""
            n = len(cracks)
            if n < 2:
                return False
            adj = {i: set() for i in range(n)}
            for i in range(n):
                for j in range(i+1, n):
                    if cracks_overlap_or_connect(cracks[i], cracks[j]):
                        adj[i].add(j)
                        adj[j].add(i)
            # BFS/DFS to test connectivity
            visited = set()
            stack = [0]
            while stack:
                u = stack.pop()
                if u in visited: 
                    continue
                visited.add(u)
                stack.extend(adj[u] - visited)
            return len(visited) == n

        # --- Build a unique display list where each atomic belongs to at most one combined
        display_items = []  # list of (type, id)
        seen_atomic = set()

        # First, add combined cracks as single entries
        for cmb_id, cmb in sorted(combined_cracks.items(), key=lambda kv: int(kv[0])):
            members = cmb.get("members", [])
            if any(m in atomic_cracks for m in members):
                display_items.append(("combined", cmb_id))
                seen_atomic.update(members)

        # Then add remaining atomic cracks
        for atom_id in sorted(atomic_cracks.keys(), key=lambda s: int(s)):
            if atom_id not in seen_atomic:
                display_items.append(("atomic", atom_id))

        # If fewer than two selectable entries, abort
        if len(display_items) < 2:
            error("Need at least two segments (atomic or combined) to combine.")
            return

        # --- Dialog
        dlg = QDialog(self.MainWindow)
        dlg.setWindowTitle("Combine Segments")
        layout = QVBoxLayout(dlg)

        listwidget = QListWidget()
        listwidget.setSelectionMode(QListWidget.MultiSelection)
        for tpe, cid in display_items:
            if tpe == "atomic":
                lbl = f"Atomic {cid}"
            else:
                members = combined_cracks[cid].get("members", [])
                lbl = f"Combined {cid} (members: {','.join(members)})"
            listwidget.addItem(lbl)
        layout.addWidget(listwidget)

        btns = QHBoxLayout()
        btn_ok = QPushButton("Combine Selected")
        btn_cancel = QPushButton("Cancel")
        btns.addWidget(btn_ok)
        btns.addWidget(btn_cancel)
        layout.addLayout(btns)

        btn_ok.clicked.connect(dlg.accept)
        btn_cancel.clicked.connect(dlg.reject)

        # --- Highlight selection
        def highlight():
            display = self.original_image.copy()
            for i, (tpe, cid) in enumerate(display_items):
                crack = atomic_cracks[cid] if tpe == "atomic" else combined_cracks[cid]
                m_full = mask_from_crack(crack)
                if np.any(m_full):
                    color = (255, 0, 0)
                    alpha = 0.25
                    if listwidget.item(i).isSelected():
                        color = (255, 255, 0)
                        alpha = 0.6
                    overlay = np.zeros_like(display)
                    overlay[m_full.astype(bool)] = color
                    display = cv2.addWeighted(display, 1, overlay, alpha, 0)
            im = display.astype(np.uint8)
            qimage = QImage(im, im.shape[1], im.shape[0], im.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            scaled = pixmap.scaled(self.ImageScreen.width(), self.ImageScreen.height(),
                                Qt.KeepAspectRatio, Qt.FastTransformation)
            self.ImageScreen.setPixmap(scaled)

        listwidget.itemSelectionChanged.connect(highlight)
        highlight()

        if dlg.exec_() != QDialog.Accepted:
            self.change_image()
            return

        selected_rows = [i.row() for i in listwidget.selectedIndexes()]
        if len(selected_rows) < 2:
            error("Select at least two segments to combine.")
            self.change_image()
            return

        # --- Gather all atomic members from selection
        selected_atomic_ids = set()
        for idx in selected_rows:
            tpe, cid = display_items[idx]
            if tpe == "atomic":
                selected_atomic_ids.add(cid)
            else:
                selected_atomic_ids.update(combined_cracks[cid].get("members", []))

        # --- Validate connectivity
        selected_cracks = [atomic_cracks[cid] for cid in selected_atomic_ids if cid in atomic_cracks]
        if not cracks_all_connected(selected_cracks):
            error("Selected cracks do not all connect (overlap or shared endpoints).")
            self.change_image()
            return

        # --- Remove any existing combined fully contained by this new merge
        to_delete = []
        for cmb_id, cmb in list(combined_cracks.items()):
            members = set(cmb.get("members", []))
            if members.issubset(selected_atomic_ids):
                to_delete.append(cmb_id)
        for cmb_id in to_delete:
            combined_cracks.pop(cmb_id, None)

        # --- Allocate a new combined id
        cmb_ids = []
        for k in combined_cracks.keys():
            try:
                cmb_ids.append(int(k))
            except:
                pass
        new_cmb_id = str(max(cmb_ids) + 1 if cmb_ids else 0)

        # --- Build a *full* combined crack (midline + edges + widths + crop)
        combined_entry = self._build_combined_crack(sorted(selected_atomic_ids, key=lambda s: int(s)))
        if combined_entry is None:
            error("Failed to build combined crack (no valid midlines or masks).")
            self.change_image()
            return

        combined_cracks[new_cmb_id] = combined_entry

        self.save_annotation()
        self.change_image()

    # crack_tool_v2.py  --- add to class CrackToolsApplication
    def clear_combined_cracks(self):
        """
        Delete (some or all) combined cracks; atomic cracks remain untouched.
        In the dialog:
        - All combined cracks are shown in yellow by default
        - Selected ones are shown in red
        """
        from PyQt5.QtWidgets import QDialog, QVBoxLayout, QListWidget, QPushButton, QHBoxLayout
        from PyQt5.QtGui import QImage, QPixmap
        import numpy as np, cv2

        if not hasattr(self, "annotation") or not isinstance(self.annotation, dict):
            error("No annotation data loaded.")
            return

        ann = self.annotation.setdefault("annotations", {})
        combined = ann.setdefault("combined_cracks", {})
        if not combined:
            error("No combined cracks to delete.")
            return

        keys_sorted = sorted(combined.keys(), key=lambda s: int(s))
        labels = []
        H, W = self.original_image.shape[:2]
        for cid in keys_sorted:
            members = combined[cid].get("members", [])
            labels.append(f"Combined {cid}  (members: {','.join(map(str, members))})")

        dlg = QDialog(self.MainWindow)
        dlg.setWindowTitle("Clear (Delete) Combined Cracks")
        layout = QVBoxLayout(dlg)
        lw = QListWidget()
        lw.setSelectionMode(QListWidget.MultiSelection)
        for lbl in labels:
            lw.addItem(lbl)
        layout.addWidget(lw)

        btns = QHBoxLayout()
        ok = QPushButton("Delete Selected")
        cancel = QPushButton("Cancel")
        btns.addWidget(ok)
        btns.addWidget(cancel)
        layout.addLayout(btns)
        ok.clicked.connect(dlg.accept)
        cancel.clicked.connect(dlg.reject)

        # Highlight function
        def highlight():
            disp = self.original_image.copy()
            for i, cid in enumerate(keys_sorted):
                mask = reconstruct_full_mask_from_crack(combined[cid], H, W)
                if not np.any(mask):
                    continue
                overlay = np.zeros_like(disp)
                if lw.item(i).isSelected():
                    overlay[mask.astype(bool)] = (255, 0, 0)  # red if selected
                    alpha = 0.6
                else:
                    overlay[mask.astype(bool)] = (255, 255, 0)  # yellow if not selected
                    alpha = 0.4
                disp = cv2.addWeighted(disp, 1, overlay, alpha, 0)
            qimage = QImage(disp, disp.shape[1], disp.shape[0], disp.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            self.ImageScreen.setPixmap(
                pixmap.scaled(self.ImageScreen.width(), self.ImageScreen.height(),
                            Qt.KeepAspectRatio, Qt.FastTransformation)
            )

        lw.itemSelectionChanged.connect(highlight)
        highlight()

        if dlg.exec_() == QDialog.Accepted:
            sel = [r.row() for r in lw.selectedIndexes()]
            for idx in sorted(sel, reverse=True):
                combined.pop(keys_sorted[idx], None)
            self.save_annotation()
            self.change_image()
        else:
            self.change_image()

    def clear_segmentation(self):
        from PyQt5.QtWidgets import QDialog, QVBoxLayout, QListWidget, QPushButton, QHBoxLayout
        import numpy as np, cv2

        if not hasattr(self, "annotation") or not isinstance(self.annotation, dict):
            error("No annotation data loaded.")
            return

        ann = self.annotation.get("annotations", {})
        atomic_cracks = ann.setdefault("atomic_cracks", {})
        combined_cracks = ann.setdefault("combined_cracks", {})

        masks = []
        labels = []
        items = []

        H, W = self.original_image.shape[:2]

        # --- Atomic cracks only ---
        for crack_id, crack in atomic_cracks.items():
            m = reconstruct_full_mask_from_crack(crack, H, W)
            masks.append(m)
            labels.append(f"Atomic {crack_id}" + ("" if np.any(m) else " (empty)"))
            items.append(("atomic", crack_id))

        if not masks:
            error("No atomic cracks to delete.")
            return

        # --- Selection dialog ---
        dlg = QDialog(self.MainWindow)
        dlg.setWindowTitle("Select Atomic Segments to Delete")
        layout = QVBoxLayout(dlg)
        listwidget = QListWidget()
        listwidget.setSelectionMode(QListWidget.MultiSelection)
        for lbl in labels:
            listwidget.addItem(lbl)
        layout.addWidget(listwidget)

        btns = QHBoxLayout()
        btn_ok = QPushButton("Delete Selected")
        btn_cancel = QPushButton("Cancel")
        btns.addWidget(btn_ok)
        btns.addWidget(btn_cancel)
        layout.addLayout(btns)

        btn_ok.clicked.connect(dlg.accept)
        btn_cancel.clicked.connect(dlg.reject)

        def highlight_selected_segments():
            display = self.original_image.copy()
            for i, m in enumerate(masks):
                color = (255, 0, 0)
                alpha = 0.25
                if listwidget.item(i).isSelected():
                    color = (255, 255, 0)
                    alpha = 0.6
                if np.any(m):
                    overlay = np.zeros_like(display)
                    overlay[m.astype(bool)] = color
                    display = cv2.addWeighted(display, 1, overlay, alpha, 0)
            from PyQt5.QtGui import QImage, QPixmap
            qimage = QImage(display, display.shape[1], display.shape[0],
                            display.strides[0], QImage.Format_RGB888)
            pixmap = QPixmap.fromImage(qimage)
            self.ImageScreen.setPixmap(
                pixmap.scaled(self.ImageScreen.width(), self.ImageScreen.height(),
                            Qt.KeepAspectRatio, Qt.FastTransformation)
            )

        listwidget.itemSelectionChanged.connect(highlight_selected_segments)
        highlight_selected_segments()

        if dlg.exec_() == QDialog.Accepted:
            selected_indices = [i.row() for i in listwidget.selectedIndexes()]
            if not selected_indices:
                self.change_image()
                return

            print(f"[DEBUG] clear_segmentation START")
            print(f"  Atomic cracks before = {list(atomic_cracks.keys())}")

            # --- Delete selected ---
            for idx in sorted(selected_indices, reverse=True):
                tpe, crack_id = items[idx]
                if tpe == "atomic":
                    print(f"[DEBUG] Deleting atomic crack_id={crack_id}")
                    atomic_cracks.pop(crack_id, None)
                    # Remove from combined_cracks members if present
                    for cid, combo in list(combined_cracks.items()):
                        # Remove deleted atomic cracks from members
                        combo["members"] = [m for m in combo.get("members", []) if m in atomic_cracks]

                        # Delete if fewer than 2 members remain
                        if len(combo["members"]) < 2:
                            combined_cracks.pop(cid, None)
                            continue

                        # Get full image size
                        H, W = self.original_image.shape[:2]

                        # --- Rebuild union mask ---
                        union_mask = np.zeros((H, W), dtype=np.uint8)
                        for m_id in combo["members"]:
                            member_crack = atomic_cracks.get(m_id)
                            if member_crack is not None:
                                union_mask |= reconstruct_full_mask_from_crack(member_crack, H, W)

                        if np.any(union_mask):
                            ys, xs = np.where(union_mask > 0)
                            y0, y1 = int(ys.min()), int(ys.max() + 1)
                            x0, x1 = int(xs.min()), int(xs.max() + 1)
                            crop = union_mask[y0:y1, x0:x1].astype(np.uint8)
                            combo["mask_crop"] = crop.tolist()
                            combo["mask_bbox"] = [int(x0), int(y0), int(x1 - x0), int(y1 - y0)]
                        else:
                            combined_cracks.pop(cid, None)

            # --- Reindex atomic cracks only ---
            # --- Reindex atomic cracks (build old->new map first) ---
            if atomic_cracks:
                old_ids_sorted = sorted(atomic_cracks.keys(), key=lambda x: int(x))
                old_to_new = {old_id: str(i) for i, old_id in enumerate(old_ids_sorted)}
                new_atomic = {old_to_new[old_id]: atomic_cracks[old_id] for old_id in old_ids_sorted}
                atomic_cracks.clear()
                atomic_cracks.update(new_atomic)

            # --- Remap combined crack members after atomic reindex, drop small ones, and rebuild full geometry ---
            if combined_cracks:
                to_delete = []
                for cid, combo in list(combined_cracks.items()):
                    members_old = combo.get("members", [])
                    # remap to new ids; keep only those still present
                    members_new = [old_to_new[m] for m in members_old if m in old_to_new]
                    members_new = sorted(members_new, key=lambda s: int(s))

                    if len(members_new) < 2:
                        to_delete.append(cid)
                        continue

                    # Recompute full combined geometry
                    combined_entry = self._build_combined_crack(members_new)
                    if combined_entry is None:
                        to_delete.append(cid)
                        continue

                    combined_cracks[cid] = combined_entry

                for cid in to_delete:
                    combined_cracks.pop(cid, None)

            self.annotation["annotations"]["atomic_cracks"] = atomic_cracks
            self.annotation["annotations"]["combined_cracks"] = combined_cracks

            # --- Save + refresh ---
            self.save_annotation()
            self.change_image()
        else:
            self.change_image()

    # ---- local helpers
    @staticmethod
    def compute_mask_metrics(gt_mask, pred_mask):
        gt = gt_mask.astype(bool); pr = pred_mask.astype(bool)
        tp = np.logical_and(gt, pr).sum()
        fp = np.logical_and(~gt, pr).sum()
        fn = np.logical_and(gt, ~pr).sum()
        tn = np.logical_and(~gt, ~pr).sum()
        precision = tp / (tp + fp + 1e-9)
        recall    = tp / (tp + fn + 1e-9)
        f1        = 2 * precision * recall / (precision + recall + 1e-9)
        iou       = tp / (tp + fp + fn + 1e-9)
        return {"precision": precision, "recall": recall, "f1": f1, "iou": iou,
                "tp": int(tp), "fp": int(fp), "fn": int(fn), "tn": int(tn)}

    @staticmethod
    def save_mask_comparison_plot(gt_mask, pred_mask, out_path, show=False):
        gt = gt_mask.astype(bool)
        pr = pred_mask.astype(bool)
        iou = np.logical_and(gt, pr)   # intersection
        oou = np.logical_and(gt, ~pr)  # missed crack
        cou = np.logical_and(~gt, pr)  # false positive
        vis = np.zeros((*gt.shape, 3), dtype=np.uint8)
        vis[iou] = [255, 255, 255]
        vis[oou] = [255,   0,   0]
        vis[cou] = [  0,   0, 255]
        if show:
            plt.figure(figsize=(8, 6))
            plt.imshow(vis); plt.title("Mask Comparison Overlay"); plt.axis("off"); plt.show()
        else:
            plt.imsave(out_path, vis)

    @staticmethod
    def _reconstruct_full_mask(crack, H, W):
        try:
            return reconstruct_full_mask_from_crack(crack, H, W)
        except Exception:
            mc = crack.get("mask_crop"); bb = crack.get("mask_bbox")
            if mc is not None and bb is not None:
                crop = np.array(mc, dtype=np.uint8)
                x, y, w, h = [int(v) for v in bb]
                x2, y2 = min(x+w, W), min(y+h, H)
                w_eff, h_eff = max(0, x2-x), max(0, y2-y)
                if h_eff > 0 and w_eff > 0:
                    crop = (crop > 0).astype(np.uint8)[:h_eff, :w_eff]
                    m = np.zeros((H, W), dtype=np.uint8)
                    m[y:y+h_eff, x:x+w_eff] = crop
                    return m
            full = np.array(crack.get("mask", []), dtype=np.uint8)
            if full.size == H*W and full.shape == (H, W):
                return (full > 0).astype(np.uint8)
            return np.zeros((H, W), dtype=np.uint8)
        
    @staticmethod
    def normals_from_mask_for_midline(midline_xy, mask, max_radius=50):
        """
        Pixel-accurate version:
        - Polygonizes the mask into exact pixel-boundary polygons using rasterio.
        - Intersects midline normals with those polygons so endpoints lie exactly on the mask edge.
        Returns (e1x, e1y, e2x, e2y, widths), plus the raw edge polygons for plotting.
        """
        import numpy as np
        from shapely.geometry import shape, LineString, Point, MultiPoint
        import rasterio.features

        H, W = mask.shape
        midline_xy = np.asarray(midline_xy, float)
        if midline_xy.ndim != 2 or midline_xy.shape[1] != 2 or len(midline_xy) < 2:
            n = len(midline_xy) if midline_xy.ndim > 0 else 0
            return (np.full(n, np.nan),) * 5, []

        # tangent + normals
        try:
            from cracktools.segmentation import compute_smooth_tangent_normals
            _, nor = compute_smooth_tangent_normals(midline_xy[:, 0], midline_xy[:, 1])
        except Exception:
            dx, dy = np.gradient(midline_xy[:, 0]), np.gradient(midline_xy[:, 1])
            nrm = np.hypot(dx, dy) + 1e-12
            tan = np.stack([dx/nrm, dy/nrm], axis=1)
            nor = np.stack([-tan[:, 1], tan[:, 0]], axis=1)

        # polygonize mask -> shapely polygons
        mask_bin = (mask > 0).astype(np.uint8)
        polygons = [shape(geom) for geom, val in rasterio.features.shapes(mask_bin, mask=mask_bin) if val == 1]
        edges = [poly.boundary for poly in polygons]

        N = len(midline_xy)
        e1x = np.full(N, np.nan); e1y = np.full(N, np.nan)
        e2x = np.full(N, np.nan); e2y = np.full(N, np.nan)
        widths_mask = np.full(N, np.nan)

        for i, (p, nvec) in enumerate(zip(midline_xy, nor)):
            if not np.all(np.isfinite(p)) or not np.all(np.isfinite(nvec)):
                continue

            # build long ray
            A = (p[0] - max_radius * nvec[0], p[1] - max_radius * nvec[1])
            B = (p[0] + max_radius * nvec[0], p[1] + max_radius * nvec[1])
            ray = LineString([A, B])

            hits = []
            for edge in edges:
                inter = edge.intersection(ray)
                if inter.is_empty:
                    continue
                if isinstance(inter, Point):
                    hits.append((inter.x, inter.y))
                elif isinstance(inter, MultiPoint):
                    for g in inter.geoms:
                        hits.append((g.x, g.y))
                elif inter.geom_type == "LineString":
                    coords = np.asarray(inter.coords, float)
                    hits.append(tuple(coords[0])); hits.append(tuple(coords[-1]))

            if len(hits) >= 2:
                dists = [np.dot([hx - p[0], hy - p[1]], nvec) for (hx, hy) in hits]
                left_pts = [(hx, hy) for (hx, hy), d in zip(hits, dists) if d < 0]
                right_pts = [(hx, hy) for (hx, hy), d in zip(hits, dists) if d > 0]
                if left_pts and right_pts:
                    lp = max(left_pts, key=lambda q: np.dot([q[0]-p[0], q[1]-p[1]], nvec))
                    rp = min(right_pts, key=lambda q: np.dot([q[0]-p[0], q[1]-p[1]], nvec))
                    e1x[i], e1y[i] = lp
                    e2x[i], e2y[i] = rp
                    widths_mask[i] = np.hypot(rp[0]-lp[0], rp[1]-lp[1])

        return (e1x, e1y, e2x, e2y, widths_mask), polygons

    @staticmethod
    def plot_mask_normals(midline, e1x, e1y, e2x, e2y, mask, contours=None,
                        spacing_px=20, show=True, out_path=None, crack_label=""):
        """
        Plot normals + crack contours (polygons) for visualization.
        - contours: list of Shapely Polygons (from rasterio.features.shapes)
        """
        import matplotlib.pyplot as plt
        import numpy as np

        H, W = mask.shape
        plt.figure(figsize=(8, 8))
        plt.imshow(mask, cmap="gray", alpha=0.5)

        # plot polygon contours
        if contours:
            for poly in contours:
                if poly.is_empty:
                    continue
                # in plot_mask_normals when drawing contours
                if poly.geom_type == "Polygon":
                    x, y = poly.exterior.xy
                    plt.plot(np.array(x) - 0.5, np.array(y) - 0.5,
                            color="orange", lw=1.0, alpha=0.8)
                    for interior in poly.interiors:
                        xi, yi = interior.xy
                        plt.plot(np.array(xi) - 0.5, np.array(yi) - 0.5,
                                color="orange", lw=0.5, alpha=0.5)
                elif poly.geom_type == "MultiPolygon":
                    for sub in poly.geoms:
                        x, y = sub.exterior.xy
                        plt.plot(x, y, color="orange", lw=1.0, alpha=0.8)

        # plot midline
        if midline is not None and len(midline) > 1:
            plt.plot(midline[:,0], midline[:,1], 'g-', lw=1.0, label="midline")

        # plot normals
        N = len(midline)
        for i in range(0, N, spacing_px):
            if np.isfinite(e1x[i]) and np.isfinite(e2x[i]):
                plt.plot([e1x[i], e2x[i]], [e1y[i], e2y[i]],
                        color="cyan", lw=0.5, alpha=0.8)
                plt.scatter([e1x[i], e2x[i]], [e1y[i], e2y[i]],
                            c=["red","blue"], s=8, marker="o", alpha=0.7)

        plt.title(f"Mask normals — {crack_label}")
        plt.axis("equal"); plt.legend(); plt.tight_layout()

        if show:
            plt.show()
        elif out_path:
            plt.savefig(out_path, dpi=200); plt.close()

    def run_mask_metrics(self, display=True):
        """
        1) Mask IoU/F1/precision/recall for current image.
        2) Per-crack width/normal validation: compare GT mask-derived widths vs saved geodesic normals.
        Only evaluates combined cracks and atomics not part of any combined.
        """
        import os, numpy as np, pandas as pd, matplotlib.pyplot as plt, cv2

        # ---- guards
        if not hasattr(self, "image") or self.image is None:
            print("⚠️ No image loaded — skipping mask metrics."); return
        if not hasattr(self, "annotation") or not self.annotation:
            print("⚠️ No annotation loaded — skipping mask metrics."); return
        if not hasattr(self, "current_mask") or self.current_mask is None:
            print("⚠️ No ground truth mask available — skipping mask metrics."); return

        ann = self.annotation.get("annotations", {})
        H, W = self.image.shape[:2]

        # ---- 1) image-level mask metrics
        pred_mask = build_combined_mask(ann.get("atomic_cracks", {}), H, W)
        metrics = self.compute_mask_metrics(self.current_mask, pred_mask)

        base_name = os.path.splitext(os.path.basename(self.name))[0]
        metrics_dir = os.path.join(self.save_folder, "metrics")
        os.makedirs(metrics_dir, exist_ok=True)

        mask_csv_path = os.path.join(metrics_dir, "mask_metrics.csv")
        row = {"image": base_name, **metrics}
        if os.path.exists(mask_csv_path):
            df = pd.read_csv(mask_csv_path)
            df = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
        else:
            df = pd.DataFrame([row])
        df.to_csv(mask_csv_path, index=False)

        vis_path = os.path.join(metrics_dir, base_name + "_iou_overlay.png")
        self.save_mask_comparison_plot(self.current_mask, pred_mask, vis_path, show=display)

        # ---- 2) per-crack midline width/normal validation
        width_csv_path = os.path.join(metrics_dir, "width_metrics.csv")
        width_rows = []

        atomic = ann.get("atomic_cracks", {}) or {}
        combined = ann.get("combined_cracks", {}) or {}

        # skip atomics already absorbed in combined
        atomics_in_combined = {m for cmb in combined.values() for m in cmb.get("members", [])}
        all_cracks = [( "atomic", cid, crack) for cid, crack in atomic.items() if cid not in atomics_in_combined]
        all_cracks += [( "combined", cid, crack) for cid, crack in combined.items()]

        for ctype, cid, crack in all_cracks:
            midline = np.asarray(crack.get("midline", []), float)
            if midline.ndim != 2 or midline.shape[1] != 2 or len(midline) < 3:
                continue  # nothing to evaluate

            crack_mask = self.current_mask  # <-- GT mask only

            # mask-based normals/widths
            (e1x_m, e1y_m, e2x_m, e2y_m, w_mask), contours = self.normals_from_mask_for_midline(
                midline, crack_mask, max_radius=50
            )

            self.plot_mask_normals(
                midline, e1x_m, e1y_m, e2x_m, e2y_m, crack_mask,
                contours=contours,
                spacing_px=20, show=True,
                crack_label=f"{ctype} {cid}"
            )

            debug_normals_path = os.path.join(metrics_dir, f"{base_name}_{ctype}{cid}_mask_normals.png")

            # edge-tracking normals
            ne = crack.get("normal_edge_points")
            w_edge = None
            if ne and isinstance(ne, dict):
                def _to_array(v):
                    if isinstance(v, list) and len(v) == 2 and isinstance(v[0], (list, tuple)):
                        return np.column_stack([v[0], v[1]]).astype(float)
                    return np.array(v, float)
                e1 = _to_array(ne.get("edge1", []))
                e2 = _to_array(ne.get("edge2", []))
                if e1.ndim == 2 and e2.ndim == 2 and len(e1) and len(e2):
                    m = min(len(e1), len(e2), len(w_mask))
                    w_edge = np.full(m, np.nan)
                    for i in range(m):
                        if np.all(np.isfinite(e1[i])) and np.all(np.isfinite(e2[i])):
                            w_edge[i] = np.hypot(e1[i,0] - e2[i,0], e1[i,1] - e2[i,1])
                    w_mask = w_mask[:m]

            if w_edge is not None:
                valid = np.isfinite(w_mask) & np.isfinite(w_edge)
                n_valid = int(valid.sum())
                if n_valid >= 3:
                    diff = w_edge[valid] - w_mask[valid]
                    mae  = float(np.mean(np.abs(diff)))
                    rmse = float(np.sqrt(np.mean(diff**2)))
                    mean_mask = float(np.mean(w_mask[valid]))
                    mean_edge = float(np.mean(w_edge[valid]))
                    wmv = w_mask[valid] - w_mask[valid].mean()
                    wev = w_edge[valid] - w_edge[valid].mean()
                    denom = (np.sqrt((wmv**2).sum()) * np.sqrt((wev**2).sum()) + 1e-12)
                    corr = float((wmv * wev).sum() / denom)

                    width_rows.append({
                        "image": base_name, "crack_type": ctype, "crack_id": cid,
                        "n_valid": n_valid,
                        "mask_width_mean": mean_mask,
                        "edge_width_mean": mean_edge,
                        "width_diff_mae": mae,
                        "width_diff_rmse": rmse,
                        "width_corr": corr
                    })

        if width_rows:
            if os.path.exists(width_csv_path):
                dfw = pd.read_csv(width_csv_path)
                dfw = pd.concat([dfw, pd.DataFrame(width_rows)], ignore_index=True)
            else:
                dfw = pd.DataFrame(width_rows)
            dfw.to_csv(width_csv_path, index=False)

        print(f"✅ Saved metrics → {os.path.join(metrics_dir, 'mask_metrics.csv')}"
            f"{' and ' + os.path.join(metrics_dir, 'width_metrics.csv') if width_rows else ''}")

